<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/app/bootstrap.php';
require dirname(__DIR__,2).'/app/BusinessSubscriptionAdminService.php';
if(isset($_SESSION['admin'])&&time()-(int)($_SESSION['last_seen']??0)>1800)unset($_SESSION['admin']);
if(empty($_SESSION['admin'])){http_response_code(403);exit('Inicia sesión desde el panel de administración.');}
$_SESSION['last_seen']=time();$pdo=db();$service=new BusinessSubscriptionAdminService($pdo);$error='';$saved='';
try{if($_SERVER['REQUEST_METHOD']==='POST'){csrf();$action=(string)($_POST['action']??'');if($action==='save'){$service->save($_POST);$saved='subscription';}elseif($action==='publish'){$service->publish((int)($_POST['business_id']??0));$saved='published';}else throw new RuntimeException('Acción no válida.');}}
catch(Throwable $e){$error=$e instanceof PDOException?'No se guardó la suscripción. Comprueba que la migración 010 esté aplicada.':$e->getMessage();http_response_code(400);}
$selected=max(0,(int)($_GET['id']??$_POST['business_id']??0));$selectedPlan=(string)($_POST['plan_code']??'');$selectedFrequency=(string)($_POST['billing_frequency']??'monthly');
$businesses=$pdo->query('SELECT b.id,t.display_name,d.slug AS destination_slug FROM businesses b JOIN business_translations t ON t.business_id=b.id AND t.locale="es" JOIN destinations d ON d.id=b.destination_id ORDER BY t.display_name')->fetchAll(PDO::FETCH_ASSOC);
$plans=$service->options();$history=[];
if($selected){$q=$pdo->prepare('SELECT bs.*,pt.name AS plan_name FROM business_subscriptions bs JOIN subscription_plan_translations pt ON pt.plan_code=bs.plan_code AND pt.locale="es" WHERE bs.business_id=? ORDER BY bs.id DESC');$q->execute([$selected]);$history=$q->fetchAll(PDO::FETCH_ASSOC);}
$requirements=json_encode(array_column($plans,'requirements','code'),JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT);
$prices=json_encode(array_column($plans,'prices','code'),JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT);
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Suscripciones | Administración</title><link rel="stylesheet" href="../assets/style.css?v=admin-navigation-20261015"></head><body><main class="wrap admin-page destination-admin" data-plan-requirements="<?=esc((string)$requirements)?>" data-plan-prices="<?=esc((string)$prices)?>"><a class="brand" href="index.php"><span>Explorando<b>Lugares</b></span></a><p><a href="negocios.php">← Volver a negocios</a></p><h1>Suscripciones</h1><p>La suscripción pertenece a cada negocio. Una cuenta podrá administrar varios negocios y cada uno tendrá su propia suscripción.</p><?php require __DIR__.'/_navigation.php'; ?>
<?php if($error):?><p class="notice" role="alert"><?=esc($error)?></p><?php endif ?><?php if($saved==='subscription'):?><p class="notice" role="status">Elección guardada. La fecha de vencimiento empezará a contar únicamente cuando el negocio se publique de forma autorizada.</p><?php elseif($saved==='published'):?><p class="notice" role="status">Negocio publicado. La vigencia comienza hoy y el vencimiento se calculó desde esta publicación efectiva.</p><?php endif ?>
<form method="post" class="destination-editor"><input type="hidden" name="csrf" value="<?=esc($_SESSION['csrf'])?>"><input type="hidden" name="action" value="save"><fieldset><legend>Registrar elección o renovación</legend><div class="destination-form-grid"><label>Negocio<select name="business_id" required><option value="">Selecciona un negocio</option><?php foreach($businesses as $business):?><option value="<?=esc($business['id'])?>" <?=business_sub_selected($selected,(int)$business['id'])?>><?=esc($business['display_name'])?> · <?=esc($business['destination_slug'])?></option><?php endforeach ?></select></label><label>Suscripción<select id="subscription-plan" name="plan_code" required><option value="">Selecciona una opción</option><?php foreach($plans as $plan):?><option value="<?=esc($plan['code'])?>" <?=($selectedPlan===$plan['code']?'selected':'')?> ><?=esc($plan['name'])?></option><?php endforeach ?></select></label><label id="frequency-field">Frecuencia<select id="subscription-frequency" name="billing_frequency"><?php foreach(['monthly'=>'Mensual','quarterly'=>'Trimestral','semiannual'=>'Semestral','annual'=>'Anual'] as $value=>$label):?><option value="<?=esc($value)?>" <?=$selectedFrequency===$value?'selected':''?>><?=esc($label)?></option><?php endforeach ?></select></label><label>Solicitar publicación desde<input type="date" name="publish_not_before" min="<?=esc((new DateTimeImmutable('today',new DateTimeZone('America/Bogota')))->format('Y-m-d'))?>" value="<?=esc((string)($_POST['publish_not_before']??''))?>"><small>No se publicará antes de esta fecha. El periodo contratado empieza el día de publicación efectiva.</small></label><label class="admin-checkbox-field"><span>Pago revisado y confirmado</span><input type="checkbox" id="payment-reviewed" name="payment_reviewed" value="1" <?=!empty($_POST['payment_reviewed'])?'checked':''?>></label></div><div id="subscription-price" class="notice" role="status" aria-live="polite">Selecciona una suscripción y frecuencia para consultar su tarifa.</div><section id="tier-requirements" class="notice" aria-live="polite" hidden></section></fieldset><p class="notice">Confirmar el pago deja la suscripción en espera de publicación. No se activa ni empieza a vencer hasta que una revisión separada apruebe y publique el negocio. Si la fecha solicitada ya pasó, se podrá publicar después y el plazo completo se contará desde ese día real.</p><button class="pill" type="submit">Guardar elección</button></form>
<?php if($selected):?><section class="destination-admin-list"><h2>Historial de suscripciones</h2><?php if(!$history):?><p>Este negocio todavía no tiene una suscripción registrada.</p><?php else:?><div class="destination-admin-table"><table><thead><tr><th>Tipo</th><th>Frecuencia e importe cotizado</th><th>Estado</th><th>No publicar antes de</th><th>Vigencia efectiva</th><th>Registro</th></tr></thead><tbody><?php foreach($history as $item):?><tr><td><?=esc($item['plan_name'])?></td><td><?=esc($item['billing_frequency']??'—')?> · <?=esc($item['quoted_amount']===null?'Tarifa no configurada':number_format((float)$item['quoted_amount'],0,',','.').' '.($item['currency']??'COP'))?></td><td><?=esc($item['status'])?></td><td><?=esc($item['publish_not_before']??'Sin fecha definida')?></td><td><?=esc($item['starts_at']??'Pendiente de publicación')?> – <?=esc($item['ends_at']??'Sin vencimiento')?></td><td><?=esc($item['created_at'])?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?><form method="post" class="subscription-publish-form"><input type="hidden" name="csrf" value="<?=esc($_SESSION['csrf'])?>"><input type="hidden" name="action" value="publish"><input type="hidden" name="business_id" value="<?=esc($selected)?>"><button class="pill" type="submit">Publicar ahora tras revisión</button><small>Valida autorización, fecha solicitada, pago, dirección, fotos del nivel y traducciones antes de publicar.</small></form></section><?php endif ?></main><script src="../assets/admin-subscriptions.js?v=subscription-flow-1" defer></script></body></html>
<?php function business_sub_selected(int $current,int $value):string{return $current===$value?'selected':'';} ?>
